  e.preventDefault();

  const resultDiv = document.getElementById('result');

  // Clear previous result
  resultDiv.hidden = true;
  resultDiv.className = '';

  // Validate that at least one checkbox is selected per question
  const q1Checked = document.querySelectorAll('input[name="question1"]:checked').length > 0;
  const q2Checked = document.querySelectorAll('input[name="question2"]:checked').length > 0;
  const q3Checked = document.querySelectorAll('input[name="question3"]:checked').length > 0;

  if (!q1Checked || !q2Checked || !q3Checked) {
    resultDiv.className = 'error';
    resultDiv.innerHTML = '<strong>Please answer all questions before submitting.</strong>';
    resultDiv.hidden = false;

    // Focus the first unanswered question
    if (!q1Checked) {
      document.getElementById('q1-python').focus();
    } else if (!q2Checked) {
      document.getElementById('q2-rust').focus();
    } else if (!q3Checked) {
      document.getElementById('q3-csharp').focus();
    }
    return;
  }

  // Get answers and check correctness
  const answers = {
    q1: getSelectedValues('question1'),
    q2: getSelectedValues('question2'),
    q3: getSelectedValues('question3')
  };

  const correctAnswers = {
    q1: ['python', 'javascript', 'ruby'], // Dynamically typed
    q2: ['php', 'typescript'], // Web development
    q3: ['cplusplus', 'rust'] // Compile to machine code
  };

  // Calculate score
  let correctCount = 0;
  let details = [];

  // Question 1
  if (arraysEqual(answers.q1.sort(), correctAnswers.q1.sort())) {
    correctCount++;
    details.push('✓ Question 1: Correct');
  } else {
    details.push('✗ Question 1: Incorrect. Correct answers: Python, JavaScript, Ruby');
  }

  // Question 2
  if (arraysEqual(answers.q2.sort(), correctAnswers.q2.sort())) {
    correctCount++;
    details.push('✓ Question 2: Correct');
  } else {
    details.push('✗ Question 2: Incorrect. Correct answers: PHP, TypeScript');
  }

  // Question 3
  if (arraysEqual(answers.q3.sort(), correctAnswers.q3.sort())) {
    correctCount++;
    details.push('✓ Question 3: Correct');
  } else {
    details.push('✗ Question 3: Incorrect. Correct answers: C++, Rust');
  }

  // Display result
  const isSuccess = correctCount === 3;
  resultDiv.className = isSuccess ? 'success' : 'error';

  let resultText = `<strong>Your Score: ${correctCount}/3</strong><br><br>`;
  resultText += details.join('<br>');

  if (isSuccess) {
    resultText = `<strong>Perfect Score! 🎉</strong><br><br>You got all ${correctCount} questions correct!`;
  }

  resultDiv.innerHTML = resultText;
  resultDiv.hidden = false;
});

function getSelectedValues(name) {
  const selected = [];
  document.querySelectorAll(`input[name="${name}"]:checked`).forEach(checkbox => {
    selected.push(checkbox.value);
  });
  return selected;
}

function arraysEqual(a, b) {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) {
    if (a[i] !== b[i]) return false;
  }
  return true;
}
