  await page.setContent(modifiedHtml, { waitUntil: "load" });
  await page.waitForTimeout(500);

  const results = await page.evaluate(async () => {
    if (!window.axe) throw new Error("axe not loaded");
    return await window.axe.run();
  });

  await browser.close();

  const wcag = results.violations.filter(v => !v.tags.includes("best-practice"));
  const bp = results.violations.filter(v => v.tags.includes("best-practice"));

  console.log("FINAL ACCESSIBILITY TEST REPORT");
  console.log("================================\n");
  console.log(`File: index.html`);
  console.log(`Status: ${wcag.length === 0 ? "✓ PASS" : "✗ FAIL"}`);
  console.log(`\nResults:`);
  console.log(`  WCAG 2.2 AA Violations: ${wcag.length}`);
  console.log(`  Best-Practice Violations: ${bp.length}`);
  console.log(`  Total Passes: ${results.passes.length}`);
  console.log(`\nRuntime: Node.js + Playwright + axe-core`);

  if (wcag.length > 0) {
    console.log("\nWCAG Violations Found:");
    wcag.forEach(v => {
      console.log(`  - ${v.id} [${v.impact}]: ${v.help}`);
      v.nodes.forEach(n => console.log(`    Target: ${n.target}`));
    });
  }

  process.exit(wcag.length > 0 ? 1 : 0);
})();
